public int findPages(int[] books, int k) {
    if (k > books.length) return -1;
    int lo = 0, hi = 0;
    for (int b : books) { lo = Math.max(lo, b); hi += b; }
    for (int x = lo; x <= hi; x++) {
        if (studentsNeeded(books, x) <= k) {
            return x;          // first feasible cap is the minimum
        }
    }
    return hi;
}

private int studentsNeeded(int[] books, int maxPages) {
    int students = 1, pages = 0;
    for (int b : books) {
        if (pages + b > maxPages) {
            students++;        // open a new student starting with this book
            pages = b;
        } else {
            pages += b;
        }
    }
    return students;
}

