public int findPages(int[] books, int k) {
    if (k > books.length) return -1;
    int lo = 0, hi = 0;
    for (int b : books) { lo = Math.max(lo, b); hi += b; }
    int ans = hi;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (studentsNeeded(books, mid) <= k) {
            ans = mid;        // feasible → remember it, try a SMALLER cap
            hi = mid - 1;
        } else {
            lo = mid + 1;     // infeasible → allow a BIGGER cap
        }
    }
    return ans;
}

private int studentsNeeded(int[] books, int maxPages) {
    int students = 1, pages = 0;
    for (int b : books) {
        if (pages + b > maxPages) {
            students++;
            pages = b;
        } else {
            pages += b;
        }
    }
    return students;
}

